{{HEAD_SCRIPTS}}  
{{SKIN}}

body.script:
//
  (function(){
    var d=document,h=d.documentElement,K='sc-theme-v3';
    var tb=d.querySelector('.theme');if(tb)tb.addEventListener('click',function(){var n=h.getAttribute('data-sc-theme')==='dark'?'light':'dark';h.setAttribute('data-sc-theme',n);try{localStorage.setItem(K,n);}catch(e){}});
    var up=d.querySelector('.sc-totop');if(up){up.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});window.addEventListener('scroll',function(){up.classList.toggle('show',window.scrollY>700);},{passive:true});}
    var nt=d.getElementById('nav-t');d.querySelectorAll('.nav a').forEach(function(a){a.addEventListener('click',function(){if(nt)nt.checked=false;});});
    // مثال الراتب في الرئيسية
    var g=d.getElementById('hc-g');if(g){
      var B=[[40000,0],[55000,.10],[70000,.15],[200000,.20],[400000,.225],[1200000,.25],[1e15,.275]],i=d.getElementById('hc-i');
      function f(n){return Math.round(n).toLocaleString('ar-EG');}
      function up2(){var G=+g.value||0,I=+i.value||0,t=Math.max(0,(G-I)*12-20000),tx=0,p=0;for(var k=0;k<B.length;k++){if(t>p)tx+=(Math.min(t,B[k][0])-p)*B[k][1];p=B[k][0];}
        var m=tx/12,n=G-I-m;d.getElementById('hc-n').textContent=f(n)+' جنيه';d.getElementById('hc-t').textContent=f(m);
        var s=G>0?100/G:0;d.getElementById('hc-ba').style.width=(n*s)+'%';d.getElementById('hc-bb').style.width=(m*s)+'%';d.getElementById('hc-bc').style.width=(I*s)+'%';}
      g.addEventListener('input',up2);i.addEventListener('input',up2);up2();}
    // مقال: وقت القراءة وفهرس المحتوى
    var pb=d.querySelector('.post .prose');if(pb){
      var w=(pb.innerText||'').trim().split(/\s+/).length,m=Math.max(1,Math.round(w/180)),r=d.getElementById('rt');if(r)r.textContent='وقت القراءة '+m+(m===1?' دقيقة':' دقائق')+' · '+w+' كلمة';
      var hs=pb.querySelectorAll('h2');if(hs.length>=3){var o=d.createElement('nav');o.className='toc';o.setAttribute('aria-label','محتويات المقال');var l='<b>في هذا المقال</b><ol>';hs.forEach(function(e,k){e.id=e.id||'s'+(k+1);l+='<li><a href="#'+e.id+'">'+e.textContent+'</a></li>';});o.innerHTML=l+'</ol>';pb.insertBefore(o,pb.firstChild);}
    }
  })();
  //
